<script setup lang="ts">
type HubunganKeluarga = 'KEPALA_KELUARGA' | 'PASANGAN' | 'ANAK' | 'ANAK_ANGKAT' | 'ANGGOTA_LAIN'
type GolonganDarah = 'A' | 'B' | 'AB' | 'O' | 'TIDAK_TAHU'
type StatusPernikahan = 'BELUM_MENIKAH' | 'MENIKAH' | 'CERAI_HIDUP' | 'CERAI_MATI'
type StatusBaptis = 'BELUM_BAPTIS' | 'SUDAH_BAPTIS'
type StatusJemaat = 'AKTIF' | 'TIDAK_AKTIF'
type Keluarga = { idKeluarga: number; namaKeluarga: string; nomorKk: string | null }
type Jemaat = { idJemaat: number; idKeluarga: number | null; namaKeluarga: string | null; hubunganKeluarga: HubunganKeluarga | null; namaLengkap: string; nik: string | null; jenisKelamin: 'LAKI_LAKI' | 'PEREMPUAN'; tempatLahir: string | null; tanggalLahir: string; golonganDarah: GolonganDarah | null; alamat: string; telepon: string | null; statusPernikahan: StatusPernikahan | null; statusBaptis: StatusBaptis | null; pekerjaan: string | null; kewarganegaraan: string | null; statusJemaat: StatusJemaat }
type FormJemaat = { idKeluarga: number | null; hubunganKeluarga: HubunganKeluarga | null; namaLengkap: string; nik: string; jenisKelamin: 'LAKI_LAKI' | 'PEREMPUAN'; tempatLahir: string; tanggalLahir: string; golonganDarah: GolonganDarah | null; alamat: string; telepon: string; statusPernikahan: StatusPernikahan | null; statusBaptis: StatusBaptis | null; pekerjaan: string; kewarganegaraan: string; statusJemaat: StatusJemaat }
type NamaField = keyof FormJemaat

const { apiFetch } = useApi()
const tokenAdmin = useCookie<string | null>('gkii_admin_token')
const authorization = computed(() => ({ Authorization: `Bearer ${tokenAdmin.value}` }))
const formAwal = (): FormJemaat => ({ idKeluarga: null, hubunganKeluarga: null, namaLengkap: '', nik: '', jenisKelamin: 'LAKI_LAKI', tempatLahir: '', tanggalLahir: '', golonganDarah: null, alamat: '', telepon: '', statusPernikahan: null, statusBaptis: null, pekerjaan: '', kewarganegaraan: 'WNI', statusJemaat: 'AKTIF' })
const form = reactive<FormJemaat>(formAwal())
const kesalahanForm = reactive<Record<NamaField, string>>({ idKeluarga: '', hubunganKeluarga: '', namaLengkap: '', nik: '', jenisKelamin: '', tempatLahir: '', tanggalLahir: '', golonganDarah: '', alamat: '', telepon: '', statusPernikahan: '', statusBaptis: '', pekerjaan: '', kewarganegaraan: '', statusJemaat: '' })
const nomorKkPencarian = ref('')
const formTerbuka = ref(false)
const idJemaatDiedit = ref<number | null>(null)
const sedangMenyimpan = ref(false)
const sedangMenghapus = ref<number | null>(null)
const pesanError = ref('')
const pesanSukses = ref('')
const ringkasanError = ref<HTMLElement | null>(null)
const { data: dataAwal, pending, error, refresh } = await useAsyncData('admin-jemaat', async () => {
  const [jemaatResponse, keluargaResponse] = await Promise.all([apiFetch<Jemaat[]>('/jemaat', { headers: authorization.value }), apiFetch<Keluarga[]>('/keluarga', { headers: authorization.value })])
  return { daftarJemaat: jemaatResponse.data, daftarKeluarga: keluargaResponse.data }
})
const daftarJemaat = computed(() => dataAwal.value?.daftarJemaat ?? [])
const daftarKeluarga = computed(() => dataAwal.value?.daftarKeluarga ?? [])
const keluargaCocokNoKk = computed(() => { const nomorKk = nomorKkPencarian.value.replace(/\D/g, ''); return nomorKk.length === 16 ? daftarKeluarga.value.find((keluarga) => keluarga.nomorKk === nomorKk) ?? null : null })
const modeEdit = computed(() => idJemaatDiedit.value !== null)
watch(() => form.idKeluarga, (idKeluarga) => { if (!idKeluarga) form.hubunganKeluarga = null })
function formatTanggal(tanggal: string) { return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(tanggal)) }
function labelHubungan(hubungan: HubunganKeluarga | null) { return ({ KEPALA_KELUARGA: 'Kepala keluarga', PASANGAN: 'Pasangan', ANAK: 'Anak', ANAK_ANGKAT: 'Anak angkat', ANGGOTA_LAIN: 'Anggota lain' } as const)[hubungan ?? 'ANGGOTA_LAIN'] }
function bersihkanKesalahan() { for (const field of Object.keys(kesalahanForm) as NamaField[]) kesalahanForm[field] = '' }
function validasiField(field: NamaField) {
  if (field === 'idKeluarga') { kesalahanForm.idKeluarga = ''; return true }
  if (field === 'hubunganKeluarga') { kesalahanForm.hubunganKeluarga = form.idKeluarga && !form.hubunganKeluarga ? 'Pilih hubungan dalam keluarga.' : ''; return !kesalahanForm.hubunganKeluarga }
  const nilai = typeof form[field] === 'string' ? form[field].trim() : ''
  if (field === 'nik' && nilai && !/^\d{16}$/.test(nilai)) { kesalahanForm.nik = 'NIK harus terdiri dari 16 digit.'; return false }
  if (['namaLengkap', 'tanggalLahir', 'alamat'].includes(field) && !nilai) { kesalahanForm[field] = 'Field ini wajib diisi.'; return false }
  kesalahanForm[field] = ''; return true
}
function validasiForm() { return (['hubunganKeluarga', 'namaLengkap', 'nik', 'tanggalLahir', 'alamat'] as NamaField[]).every(validasiField) }
function bukaFormTambah() { Object.assign(form, formAwal()); nomorKkPencarian.value = ''; bersihkanKesalahan(); idJemaatDiedit.value = null; pesanError.value = ''; formTerbuka.value = true }
function bukaFormEdit(jemaat: Jemaat) { Object.assign(form, { idKeluarga: jemaat.idKeluarga, hubunganKeluarga: jemaat.hubunganKeluarga, namaLengkap: jemaat.namaLengkap, nik: jemaat.nik ?? '', jenisKelamin: jemaat.jenisKelamin, tempatLahir: jemaat.tempatLahir ?? '', tanggalLahir: jemaat.tanggalLahir, golonganDarah: jemaat.golonganDarah, alamat: jemaat.alamat, telepon: jemaat.telepon ?? '', statusPernikahan: jemaat.statusPernikahan, statusBaptis: jemaat.statusBaptis, pekerjaan: jemaat.pekerjaan ?? '', kewarganegaraan: jemaat.kewarganegaraan ?? 'WNI', statusJemaat: jemaat.statusJemaat }); nomorKkPencarian.value = daftarKeluarga.value.find((keluarga) => keluarga.idKeluarga === jemaat.idKeluarga)?.nomorKk ?? ''; bersihkanKesalahan(); idJemaatDiedit.value = jemaat.idJemaat; pesanError.value = ''; formTerbuka.value = true }
function pilihKeluargaDariNoKk() { if (keluargaCocokNoKk.value) form.idKeluarga = keluargaCocokNoKk.value.idKeluarga }
function tutupForm() { if (!sedangMenyimpan.value) { formTerbuka.value = false; pesanError.value = ''; bersihkanKesalahan() } }
async function simpanJemaat() { pesanError.value = ''; pesanSukses.value = ''; if (!validasiForm()) { pesanError.value = 'Periksa kembali data jemaat yang wajib diisi.'; await nextTick(); ringkasanError.value?.focus(); return }; sedangMenyimpan.value = true; const body = { ...form, namaLengkap: form.namaLengkap.trim(), nik: form.nik.trim() || null, tempatLahir: form.tempatLahir.trim() || null, alamat: form.alamat.trim(), telepon: form.telepon.trim() || null, pekerjaan: form.pekerjaan.trim() || null, kewarganegaraan: form.kewarganegaraan.trim() || null }; try { if (modeEdit.value && idJemaatDiedit.value) { await apiFetch<Jemaat>(`/jemaat/${idJemaatDiedit.value}`, { method: 'PUT', headers: authorization.value, body }); pesanSukses.value = 'Data jemaat berhasil diperbarui.' } else { await apiFetch<Jemaat>('/jemaat', { method: 'POST', headers: authorization.value, body }); pesanSukses.value = 'Data jemaat berhasil ditambahkan.' }; formTerbuka.value = false; await refresh() } catch (error: unknown) { const fetchError = error as { data?: { message?: string } }; pesanError.value = fetchError.data?.message ?? 'Data jemaat belum dapat disimpan. Silakan coba kembali.' } finally { sedangMenyimpan.value = false } }
async function hapusJemaat(jemaat: Jemaat) { if (!window.confirm(`Hapus jemaat "${jemaat.namaLengkap}"? Tindakan ini tidak dapat dibatalkan.`)) return; pesanError.value = ''; pesanSukses.value = ''; sedangMenghapus.value = jemaat.idJemaat; try { await apiFetch<null>(`/jemaat/${jemaat.idJemaat}`, { method: 'DELETE', headers: authorization.value }); pesanSukses.value = 'Data jemaat berhasil dihapus.'; await refresh() } catch (error: unknown) { const fetchError = error as { data?: { message?: string } }; pesanError.value = fetchError.data?.message ?? 'Data jemaat belum dapat dihapus. Silakan coba kembali.' } finally { sedangMenghapus.value = null } }
useHead({ title: 'Jemaat | Admin GKII Jajar Solo' })
definePageMeta({ layout: 'admin', middleware: ['admin'] })
</script>

<template><div>
  <div class="page-heading"><div><p class="page-label mb-2">MANAJEMEN JEMAAT</p><h1 class="h2 mb-2">Jemaat</h1><p class="text-secondary mb-0">Catat data pribadi jemaat, lalu hubungkan ke keluarga jika diperlukan.</p></div><button type="button" class="btn btn-gkii-primary" @click="bukaFormTambah">Tambah Jemaat</button></div>
  <div v-if="pesanSukses" class="alert alert-success" role="status">{{ pesanSukses }}</div><div v-if="pesanError && !formTerbuka" class="alert alert-danger" role="alert">{{ pesanError }}</div>
  <section class="data-panel"><div class="data-panel-header"><div><h2 class="h5 mb-1">Daftar Jemaat</h2><p class="text-secondary small mb-0">{{ daftarJemaat.length }} jemaat tercatat</p></div><button type="button" class="btn btn-outline-gkii" :disabled="pending" @click="refresh()">Muat Ulang</button></div><div v-if="pending" class="p-4" aria-live="polite" aria-busy="true"><div class="placeholder-glow"><span class="placeholder col-12 mb-3"></span><span class="placeholder col-10 mb-3"></span></div></div><div v-else-if="daftarJemaat.length" class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nama</th><th>Keluarga</th><th>Jenis kelamin</th><th>Status</th><th>Kontak</th><th class="text-end">Aksi</th></tr></thead><tbody><tr v-for="jemaat in daftarJemaat" :key="jemaat.idJemaat"><td><p class="mb-1 fw-semibold">{{ jemaat.namaLengkap }}</p><small class="text-secondary">{{ formatTanggal(jemaat.tanggalLahir) }}</small></td><td><span v-if="jemaat.namaKeluarga">{{ jemaat.namaKeluarga }}<small class="d-block text-secondary">{{ labelHubungan(jemaat.hubunganKeluarga) }}</small></span><span v-else class="text-secondary">Belum dihubungkan</span></td><td>{{ jemaat.jenisKelamin === 'LAKI_LAKI' ? 'Laki-laki' : 'Perempuan' }}</td><td><span class="status-badge">{{ jemaat.statusJemaat === 'AKTIF' ? 'Aktif' : 'Tidak aktif' }}</span></td><td>{{ jemaat.telepon || '—' }}</td><td class="text-end"><div class="d-inline-flex gap-2"><button type="button" class="btn btn-sm btn-outline-gkii" @click="bukaFormEdit(jemaat)">Edit</button><button type="button" class="btn btn-sm btn-outline-danger" :disabled="sedangMenghapus === jemaat.idJemaat" @click="hapusJemaat(jemaat)">{{ sedangMenghapus === jemaat.idJemaat ? 'Menghapus...' : 'Hapus' }}</button></div></td></tr></tbody></table></div><div v-else class="empty-state p-5 text-center"><h2 class="h5 mb-2">{{ error ? 'Data belum dapat dimuat' : 'Belum ada jemaat' }}</h2><p class="text-secondary mb-3">{{ error ? 'Periksa koneksi backend atau token login, lalu coba muat ulang.' : 'Tambahkan data jemaat pertama.' }}</p><button v-if="!error" type="button" class="btn btn-gkii-primary" @click="bukaFormTambah">Tambah Jemaat</button></div></section>
  <div v-if="formTerbuka" class="modal-backdrop" @click.self="tutupForm" @keydown.esc="tutupForm"><section class="form-modal" role="dialog" aria-modal="true" aria-labelledby="judulFormJemaat"><div class="form-modal-header"><div><p class="page-label mb-2">{{ modeEdit ? 'UBAH JEMAAT' : 'TAMBAH JEMAAT' }}</p><h2 id="judulFormJemaat" class="h4 mb-0">{{ modeEdit ? 'Perbarui data jemaat' : 'Catat jemaat baru' }}</h2></div><button type="button" class="close-button" aria-label="Tutup formulir jemaat" :disabled="sedangMenyimpan" @click="tutupForm">Tutup</button></div><form @submit.prevent="simpanJemaat"><div v-if="pesanError" ref="ringkasanError" class="alert alert-danger" role="alert" tabindex="-1">{{ pesanError }}</div><div class="row g-3"><div class="col-12"><label for="nomorKk" class="form-label">Cari dengan nomor KK <span class="text-secondary">(opsional)</span></label><input id="nomorKk" v-model="nomorKkPencarian" class="form-control" inputmode="numeric" maxlength="16" placeholder="Masukkan 16 digit nomor KK"><div v-if="nomorKkPencarian && !keluargaCocokNoKk" class="form-text">Nomor KK belum ditemukan. Jemaat tetap dapat disimpan tanpa keluarga.</div><div v-else-if="keluargaCocokNoKk" class="form-text">Ditemukan keluarga <strong>{{ keluargaCocokNoKk.namaKeluarga }}</strong>. <button type="button" class="btn btn-link p-0 align-baseline" @click="pilihKeluargaDariNoKk">Hubungkan jemaat ini</button></div></div><div class="col-12"><label for="idKeluarga" class="form-label">Keluarga <span class="text-secondary">(opsional)</span></label><select id="idKeluarga" v-model.number="form.idKeluarga" class="form-select"><option :value="null">Belum dihubungkan ke keluarga</option><option v-for="keluarga in daftarKeluarga" :key="keluarga.idKeluarga" :value="keluarga.idKeluarga">{{ keluarga.namaKeluarga }}{{ keluarga.nomorKk ? ` — ${keluarga.nomorKk}` : '' }}</option></select></div><div v-if="form.idKeluarga" class="col-12"><label for="hubunganKeluarga" class="form-label">Hubungan dalam keluarga</label><select id="hubunganKeluarga" v-model="form.hubunganKeluarga" class="form-select" :class="{ 'is-invalid': kesalahanForm.hubunganKeluarga }" @blur="validasiField('hubunganKeluarga')"><option :value="null" disabled>Pilih hubungan</option><option value="KEPALA_KELUARGA">Kepala keluarga</option><option value="PASANGAN">Pasangan</option><option value="ANAK">Anak</option><option value="ANAK_ANGKAT">Anak angkat</option><option value="ANGGOTA_LAIN">Anggota lain</option></select><div class="invalid-feedback">{{ kesalahanForm.hubunganKeluarga }}</div></div><div class="col-12"><label for="namaLengkap" class="form-label">Nama lengkap</label><input id="namaLengkap" v-model="form.namaLengkap" class="form-control" :class="{ 'is-invalid': kesalahanForm.namaLengkap }" @blur="validasiField('namaLengkap')"><div class="invalid-feedback">{{ kesalahanForm.namaLengkap }}</div></div><div class="col-md-6"><label for="nik" class="form-label">NIK <span class="text-secondary">(opsional)</span></label><input id="nik" v-model="form.nik" class="form-control" inputmode="numeric" maxlength="16" :class="{ 'is-invalid': kesalahanForm.nik }" placeholder="16 digit NIK" @blur="validasiField('nik')"><div class="invalid-feedback">{{ kesalahanForm.nik }}</div></div><div class="col-md-6"><label for="jenisKelamin" class="form-label">Jenis kelamin</label><select id="jenisKelamin" v-model="form.jenisKelamin" class="form-select"><option value="LAKI_LAKI">Laki-laki</option><option value="PEREMPUAN">Perempuan</option></select></div><div class="col-md-6"><label for="tempatLahir" class="form-label">Tempat lahir <span class="text-secondary">(opsional)</span></label><input id="tempatLahir" v-model="form.tempatLahir" class="form-control"></div><div class="col-md-6"><label for="tanggalLahir" class="form-label">Tanggal lahir</label><input id="tanggalLahir" v-model="form.tanggalLahir" type="date" class="form-control" :class="{ 'is-invalid': kesalahanForm.tanggalLahir }" @blur="validasiField('tanggalLahir')"><div class="invalid-feedback">{{ kesalahanForm.tanggalLahir }}</div></div><div class="col-md-6"><label for="golonganDarah" class="form-label">Golongan darah <span class="text-secondary">(opsional)</span></label><select id="golonganDarah" v-model="form.golonganDarah" class="form-select"><option :value="null">Belum diketahui</option><option value="A">A</option><option value="B">B</option><option value="AB">AB</option><option value="O">O</option><option value="TIDAK_TAHU">Tidak tahu</option></select></div><div class="col-md-6"><label for="statusPernikahan" class="form-label">Status pernikahan <span class="text-secondary">(opsional)</span></label><select id="statusPernikahan" v-model="form.statusPernikahan" class="form-select"><option :value="null">Belum diisi</option><option value="BELUM_MENIKAH">Belum menikah</option><option value="MENIKAH">Menikah</option><option value="CERAI_HIDUP">Cerai hidup</option><option value="CERAI_MATI">Cerai mati</option></select></div><div class="col-md-6"><label for="statusBaptis" class="form-label">Status baptis <span class="text-secondary">(opsional)</span></label><select id="statusBaptis" v-model="form.statusBaptis" class="form-select"><option :value="null">Belum diisi</option><option value="BELUM_BAPTIS">Belum baptis</option><option value="SUDAH_BAPTIS">Sudah baptis</option></select></div><div class="col-12"><label for="alamat" class="form-label">Alamat</label><textarea id="alamat" v-model="form.alamat" rows="3" class="form-control" :class="{ 'is-invalid': kesalahanForm.alamat }" @blur="validasiField('alamat')"></textarea><div class="invalid-feedback">{{ kesalahanForm.alamat }}</div></div><div class="col-md-6"><label for="pekerjaan" class="form-label">Pekerjaan <span class="text-secondary">(opsional)</span></label><input id="pekerjaan" v-model="form.pekerjaan" class="form-control"></div><div class="col-md-6"><label for="kewarganegaraan" class="form-label">Kewarganegaraan <span class="text-secondary">(opsional)</span></label><input id="kewarganegaraan" v-model="form.kewarganegaraan" class="form-control"></div><div class="col-md-6"><label for="telepon" class="form-label">Telepon <span class="text-secondary">(opsional)</span></label><input id="telepon" v-model="form.telepon" type="tel" class="form-control"></div><div class="col-md-6"><label for="statusJemaat" class="form-label">Status jemaat</label><select id="statusJemaat" v-model="form.statusJemaat" class="form-select"><option value="AKTIF">Aktif</option><option value="TIDAK_AKTIF">Tidak aktif</option></select></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button type="button" class="btn btn-outline-gkii" :disabled="sedangMenyimpan" @click="tutupForm">Batal</button><button type="submit" class="btn btn-gkii-primary" :disabled="sedangMenyimpan">{{ sedangMenyimpan ? 'Menyimpan...' : modeEdit ? 'Simpan Perubahan' : 'Simpan Jemaat' }}</button></div></form></section></div>
</div></template>

<style scoped>
.page-heading,.data-panel-header,.form-modal-header{align-items:flex-start;display:flex;gap:1rem;justify-content:space-between}.page-heading{margin-bottom:1.5rem}.page-label{color:var(--gkii-gold-500);font-size:.72rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.data-panel{background:var(--gkii-surface);border:1px solid var(--gkii-border);box-shadow:0 .5rem 1.5rem rgb(18 63 50 / 6%)}.data-panel-header{border-bottom:1px solid var(--gkii-border);padding:1.25rem 1.5rem}th{background:var(--gkii-cream);color:var(--gkii-green-900);font-size:.75rem;letter-spacing:.08em;text-transform:uppercase}.status-badge{background:var(--gkii-green-100);border-radius:999px;color:var(--gkii-green-900);font-size:.75rem;font-weight:700;padding:.35rem .65rem}.empty-state{background:var(--gkii-surface)}.placeholder{background-color:var(--gkii-green-100)}.modal-backdrop{align-items:center;background:rgb(0 0 0 / 55%);display:flex;inset:0;justify-content:center;padding:1rem;position:fixed;z-index:1100}.form-modal{background:var(--gkii-surface);box-shadow:0 1.5rem 4rem rgb(0 0 0 / 28%);max-height:calc(100vh - 2rem);overflow-y:auto;padding:1.5rem;width:min(100%,48rem)}.form-modal-header{border-bottom:1px solid var(--gkii-border);margin-bottom:1.5rem;padding-bottom:1rem}.form-control,.form-select{min-height:44px}textarea.form-control{min-height:auto}.close-button{background:transparent;border:1px solid var(--gkii-border);color:var(--gkii-green-900);min-height:44px;padding:0 .9rem}.close-button:hover{background:var(--gkii-cream)}.btn:focus-visible,.close-button:focus-visible,.form-control:focus-visible,.form-select:focus-visible{outline:3px solid var(--gkii-gold-500);outline-offset:2px}@media(max-width:575.98px){.page-heading,.data-panel-header,.form-modal-header{align-items:stretch;flex-direction:column}.form-modal{padding:1.25rem}}
</style>
